// Central implementation. Consumer copies are generated; the adoption gate checks their bytes.
import assert from 'node:assert/strict';

export function surfaceCases(registry, scenarios) {
  const surfaces = registry.surfaces.filter((surface) => surface.contract);
  assert.ok(surfaces.length, 'No registered browser surfaces');
  assert.equal(new Set(surfaces.map((surface) => surface.id)).size, surfaces.length, 'Duplicate surface IDs');
  for (const surface of surfaces) {
    assert.ok(CONTRACTS[surface.contract], `Unknown contract: ${surface.contract}`);
    assert.deepEqual(
      surface.states,
      surface.contract.endsWith('summary') ? ['collapsed', 'expanded'] : ['open'],
      `Missing required states: ${surface.id}`,
    );
    assert.equal(typeof scenarios[surface.scenario], 'function', `Missing scenario: ${surface.id}`);
  }
  return surfaces.flatMap((surface) =>
    surface.states.flatMap((state) =>
      [1440, 375].map((width) => ({ surface, state, width, title: `${surface.id} / ${state} / ${width}` })),
    ),
  );
}

export async function checkSurface(page, surface, state, expect, testInfo) {
  const target = page.locator(surface.selector);
  await expect(target, surface.id).toHaveCount(1);
  await expect(target, surface.id).toBeVisible();
  await page.evaluate(() => document.fonts.ready);
  if (state === 'collapsed') await expect(target).not.toHaveAttribute('open', '');
  if (state === 'expanded') {
    await target.locator('summary').click();
    await expect(target).toHaveAttribute('open', '');
    await expect(target.locator('li').first()).toBeVisible();
  }
  if (surface.contract === 'menu') await checkMenuText(target, surface.id, expect);
  await checkIcons(target, surface.id, expect);
  await checkScale(target, surface, expect, testInfo);
  const contract = CONTRACTS[surface.contract];
  assert.ok(contract, `Unknown contract: ${surface.contract}`);
  const values = await target.evaluate(
    (element, { rules, defaults }) => {
      const actual = getComputedStyle(element);
      const probe = document.createElement('span');
      // Void controls cannot render children. Keep the probe beside the target,
      // inside the same shadow root, and carry its resolved token roles across.
      probe.style.cssText = 'position:absolute;visibility:hidden;pointer-events:none;';
      element.parentNode.append(probe);
      const result = {};
      for (const [property, token] of Object.entries(rules)) {
        const tokenValue = actual.getPropertyValue(token).trim();
        if (!tokenValue && !defaults[token]) throw Error(`Missing token ${token}`);
        probe.style.setProperty(token, tokenValue || defaults[token]);
        probe.style.setProperty(property, `var(${token})`);
        result[property] = {
          actual: actual.getPropertyValue(property),
          expected: getComputedStyle(probe).getPropertyValue(property),
          token,
        };
      }
      probe.remove();
      return result;
    },
    { rules: contract, defaults: TOKEN_DEFAULTS },
  );
  await testInfo.attach(`surface-${surface.id}`, {
    body: JSON.stringify({ id: surface.id, state, width: page.viewportSize().width, values }, null, 2),
    contentType: 'application/json',
  });
  for (const [property, value] of Object.entries(values)) {
    const debt = surface.debt?.[property];
    if (debt) {
      expect(value.expected, `${surface.id}: reviewed token expectation changed`).toBe(debt.expected);
      expect(value.actual, `${surface.id}: remove resolved debt or fix new drift (${debt.reason})`).toBe(debt.actual);
      expect(value.actual, `${surface.id}: remove obsolete debt`).not.toBe(value.expected);
    } else {
      expect(value.actual, `${surface.id}: ${property} must use ${value.token}`).toBe(value.expected);
    }
  }
}

// Everything a surface draws comes from the shared vocabulary: its two families, four sizes and two
// weights with Roboto's own spacing, its text colours, its paint (backgrounds, borders, outlines and
// shadows take only the vocabulary's colours), and the one corner, the pill and a circle. Generated
// text in `::before` and `::after`, placeholders and SVG labels are text like any other. The family a
// surface asks for must also have a loaded face, or the browser draws a fallback while every computed
// style still names the family. A framework default or a utility class that reintroduces any other
// value fails here, whatever the source scan saw. The allowed values resolve in the surface's own
// context, so a host theme override is honoured. A reviewed exception is a `scaleDebt` entry naming
// the exact value and the reason.
async function checkScale(target, surface, expect, testInfo) {
  const found = await target.evaluate(
    async (root, { scale, defaults }) => {
      // Sample the settled theme, not a colour transition another check has just started.
      await Promise.all(
        root
          .getAnimations({ subtree: true })
          .filter(
            (animation) =>
              animation.playState === 'running' && animation.effect?.getComputedTiming().iterations !== Infinity,
          )
          .map((animation) => animation.finished.catch(() => {})),
      );
      await document.fonts.ready;
      const probe = document.createElement('span');
      probe.style.cssText = 'position:absolute;visibility:hidden;pointer-events:none;';
      root.parentNode.append(probe);
      const allowed = {};
      for (const [property, tokens] of Object.entries(scale)) {
        // Paint roles resolve through `color`: every colour property computes the same way.
        const resolved = property === 'paint' ? 'color' : property === 'shadow' ? 'box-shadow' : property;
        allowed[property] = new Set(
          tokens.map((token) => {
            probe.style.setProperty(resolved, `var(${token}, ${defaults[token]})`);
            const value = getComputedStyle(probe).getPropertyValue(resolved);
            probe.style.removeProperty(resolved);
            return property === 'font-family' ? value.split(',')[0].replace(/["']/g, '').trim() : value;
          }),
        );
      }
      probe.style.setProperty('font-family', `var(--cedar-font-family, ${defaults['--cedar-font-family']})`);
      const shared = getComputedStyle(probe).fontFamily.split(',')[0].replace(/["']/g, '').trim();
      probe.remove();
      allowed['border-radius'].add('0px').add('50%');
      allowed.paint.add('rgba(0, 0, 0, 0)');
      // A shadow is the overlay or dialog shadow, or one drawn only in the vocabulary's colours.
      const shadowColors = new Set([...allowed.shadow].flatMap((shadow) => shadow.match(/rgba?\([^)]*\)/g) ?? []));
      const found = new Map();
      const note = (property, value, element, part = '') => {
        if (!found.has(`${property}|${value}`)) {
          const name = typeof element.className === 'string' ? element.className.trim().split(/\s+/)[0] : '';
          found.set(`${property}|${value}`, {
            property,
            value,
            element: element.tagName.toLowerCase() + (name ? `.${name}` : '') + part,
          });
        }
      };
      const faces = new Set();
      const typography = (style, element, part, color = style.color) => {
        if (!allowed['font-size'].has(style.fontSize)) note('font-size', style.fontSize, element, part);
        if (!allowed['font-weight'].has(style.fontWeight)) note('font-weight', style.fontWeight, element, part);
        const family = style.fontFamily.split(',')[0].replace(/["']/g, '').trim();
        if (!allowed['font-family'].has(family)) note('font-family', family, element, part);
        if (family === shared) faces.add(`${family}|${style.fontWeight}`);
        if (!allowed.color.has(color)) note('color', color, element, part);
        if (style.letterSpacing !== 'normal' && style.letterSpacing !== '0px')
          note('letter-spacing', style.letterSpacing, element, part);
      };
      const sides = ['Top', 'Right', 'Bottom', 'Left'];
      const paint = (style, element, part) => {
        if (!allowed.paint.has(style.backgroundColor)) note('background-color', style.backgroundColor, element, part);
        for (const side of sides) {
          const color = style[`border${side}Color`];
          if (
            style[`border${side}Style`] !== 'none' &&
            parseFloat(style[`border${side}Width`]) > 0 &&
            !allowed.paint.has(color)
          )
            note('border-color', color, element, part);
        }
        if (
          // `auto` is the browser's own focus ring, which no stylesheet paints.
          !['none', 'auto'].includes(style.outlineStyle) &&
          parseFloat(style.outlineWidth) > 0 &&
          !allowed.paint.has(style.outlineColor)
        )
          note('outline-color', style.outlineColor, element, part);
        if (!allowed.shadow.has(style.boxShadow))
          for (const color of style.boxShadow.match(/rgba?\([^)]*\)/g) ?? [])
            if (!allowed.paint.has(color) && !shadowColors.has(color)) note('box-shadow', color, element, part);
      };
      const corners = (style, element, part, full) => {
        for (const corner of ['TopLeft', 'TopRight', 'BottomRight', 'BottomLeft']) {
          const radius = style[`border${corner}Radius`];
          if (!allowed['border-radius'].has(radius) && !(radius.endsWith('px') && parseFloat(radius) >= full - 0.5))
            note('border-radius', radius, element, part);
        }
      };
      const drawn = (style) =>
        sides.some((side) => style[`border${side}Style`] !== 'none' && parseFloat(style[`border${side}Width`]) > 0) ||
        style.backgroundColor !== 'rgba(0, 0, 0, 0)';
      // Text kept for assistive technology inside a clipped one-pixel box is not drawn.
      const hidden = (element, style) => {
        const rect = element.getBoundingClientRect();
        return (
          (rect.width <= 1 || rect.height <= 1) &&
          (style.overflow === 'hidden' || style.clip !== 'auto' || style.clipPath !== 'none')
        );
      };
      // Icons and the box Material draws as a checkbox's mark are glyphs, whose shapes belong to the
      // symbol. The browser paints a native checkbox's mark with the same 2px corners, which no
      // computed style reports. A label an SVG sets in `<text>` is not a glyph.
      const glyphs = 'svg, .mdc-checkbox__background';
      const inspect = (element) => {
        if (!element.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true })) return false;
        // A ripple is the trace of a click, fading on a timer; what it paints depends on when the walk reads it.
        if (element.matches('.mat-ripple-element')) return false;
        const style = getComputedStyle(element);
        if (hidden(element, style)) return false;
        if (element instanceof SVGTextContentElement) {
          if (element.textContent.trim()) typography(style, element, '', style.fill);
          return true;
        }
        if (element.closest(glyphs)) return true;
        const text =
          // A run of punctuation alone, such as a separating dash, is a glyph rather than prose.
          [...element.childNodes].some(
            (node) => node.nodeType === Node.TEXT_NODE && /[\p{L}\p{N}]/u.test(node.textContent),
          ) || element.matches('input:not([type=checkbox]):not([type=radio]), select, textarea');
        if (text) typography(style, element, '');
        if (
          element.matches('input[placeholder]:placeholder-shown, textarea[placeholder]:placeholder-shown') &&
          element.placeholder.trim()
        )
          typography(getComputedStyle(element, '::placeholder'), element, '::placeholder');
        paint(style, element, '');
        if (drawn(style)) {
          // A corner that rounds its whole box is the pill, however a framework spells it.
          const rect = element.getBoundingClientRect();
          corners(style, element, '', Math.min(rect.width, rect.height) / 2);
        }
        for (const part of ['::before', '::after']) {
          const generated = getComputedStyle(element, part);
          if (generated.content === 'none' || generated.content === 'normal' || generated.display === 'none') continue;
          // Generated words are text; a lone separator such as a middle dot is a glyph.
          if (/^["'].*[\p{L}\p{N}].*["']$/u.test(generated.content)) typography(generated, element, part);
          paint(generated, element, part);
          if (drawn(generated))
            corners(
              generated,
              element,
              part,
              Math.min(parseFloat(generated.width) || 0, parseFloat(generated.height) || 0) / 2,
            );
        }
        return true;
      };
      // Another CEDAR component embedded here is checked by its own repository's surfaces.
      const visit = (parent) => {
        for (const element of parent.children) {
          if (/^cedar-embeddable-/.test(element.localName)) continue;
          if (!inspect(element)) continue;
          if (element.shadowRoot) visit(element.shadowRoot);
          visit(element);
        }
      };
      inspect(root);
      if (root.shadowRoot) visit(root.shadowRoot);
      visit(root);
      for (const face of faces) {
        const [family, weight] = face.split('|');
        const loaded = [...document.fonts].some((candidate) => {
          if (candidate.family.replace(/["']/g, '') !== family || candidate.status !== 'loaded') return false;
          const [low, high = low] = candidate.weight
            .replace('normal', '400')
            .replace('bold', '700')
            .split(/\s+/)
            .map(Number);
          return Number(weight) >= low && Number(weight) <= high;
        });
        if (!loaded) note('font-face', `${family} ${weight} has no loaded face`, root);
      }
      return [...found.values()];
    },
    { scale: SCALE, defaults: TOKEN_DEFAULTS },
  );
  await testInfo.attach(`scale-${surface.id}`, {
    body: JSON.stringify({ id: surface.id, width: target.page().viewportSize().width, found }, null, 2),
    contentType: 'application/json',
  });
  const reviewed = new Set((surface.scaleDebt ?? []).map((debt) => `${debt.property}: ${debt.value}`));
  const drift = found.filter((value) => !reviewed.has(`${value.property}: ${value.value}`));
  expect(drift, `${surface.id}: values outside the shared vocabulary`).toEqual([]);
}

// A correctly themed panel is insufficient when a button or nested label overrides it.
async function checkMenuText(target, id, expect) {
  const differences = await target.evaluate(async (menu) => {
    const properties = ['font-family', 'font-size', 'font-weight', 'line-height', 'color'];
    const actions = [...menu.querySelectorAll('button, a, [role="menuitem"], [role="menuitemradio"]')];
    const labels = actions.flatMap((action) => [action, ...action.querySelectorAll('span:not([aria-hidden="true"])')]);
    const icons = [...menu.querySelectorAll('cedar-icon, app-icon, mat-icon, svg')];
    const original = menu.getAttribute('style');
    const failures = [];
    try {
      for (const alternate of [false, true]) {
        if (alternate) {
          menu.style.setProperty('--cedar-color-primary', 'rgb(101, 37, 142)');
          menu.style.setProperty('--cedar-font-family', 'monospace');
        }
        // Read the settled theme, not the first frame of a consumer's colour transition.
        await Promise.all(
          menu
            .getAnimations({ subtree: true })
            .filter(
              (animation) =>
                animation.playState === 'running' && animation.effect?.getComputedTiming().iterations !== Infinity,
            )
            .map((animation) => animation.finished.catch(() => {})),
        );
        const expected = getComputedStyle(menu);
        if (alternate && (expected.color !== 'rgb(101, 37, 142)' || expected.fontFamily !== 'monospace')) {
          failures.push({ alternate, reason: 'Menu surface ignores the active theme' });
        }
        for (const icon of icons) {
          if (getComputedStyle(icon).color !== expected.color) {
            failures.push({
              alternate,
              icon: icon.tagName,
              property: 'color',
              actual: getComputedStyle(icon).color,
              expected: expected.color,
            });
          }
        }
        for (const label of labels) {
          const actual = getComputedStyle(label);
          for (const property of properties) {
            if (actual.getPropertyValue(property) !== expected.getPropertyValue(property)) {
              failures.push({
                alternate,
                label: label.textContent.trim(),
                property,
                actual: actual.getPropertyValue(property),
                expected: expected.getPropertyValue(property),
              });
            }
          }
        }
      }
    } finally {
      if (original === null) menu.removeAttribute('style');
      else menu.setAttribute('style', original);
    }
    return { actions: actions.length, failures };
  });
  expect(differences.actions, `${id}: menu must exercise real actions`).toBeGreaterThan(0);
  expect(differences.failures, `${id}: menu labels must inherit central typography and theme`).toEqual([]);
}

// Shared by every registered surface and by whole-page checks. Text colour is
// intentionally not the expected value: that is the inheritance bug this detects.
export async function checkIcons(target, id, expect) {
  const failures = await target
    .locator('svg[data-cedar-icon], mat-icon, .material-icons, .fa, .glyphicon')
    .evaluateAll((icons) => {
      const failures = [];
      for (const icon of icons) {
        if (!icon.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true })) continue;
        const style = getComputedStyle(icon);
        const probe = document.createElement('span');
        probe.style.color =
          style.getPropertyValue('--cedar-icon-color').trim() ||
          style.getPropertyValue('--cedar-color-primary').trim() ||
          '#0f7686';
        icon.parentNode.append(probe);
        const expected = getComputedStyle(probe).color;
        probe.remove();
        if (
          style.color !== expected ||
          style.backgroundColor !== 'rgba(0, 0, 0, 0)' ||
          style.boxShadow !== 'none' ||
          style.textShadow !== 'none'
        ) {
          failures.push({
            icon: icon.getAttribute('data-cedar-icon') || icon.textContent.trim(),
            color: style.color,
            expected,
            background: style.backgroundColor,
            shadow: style.boxShadow,
          });
        }
      }
      return failures;
    });
  expect(failures, `${id}: shared icon foreground and flat glyph surface`).toEqual([]);
}
